package com.primehr.security;
import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;
@Component public class RspPlanningPermissionGuard {public static final String FEATURE="primehr.rsp-recruitment-planning";private final AdministrativeAuthorizationClient client;public RspPlanningPermissionGuard(AdministrativeAuthorizationClient c){client=c;}public EffectiveFeaturePermission require(PrimeHrAction action,String token){if(token==null||!token.regionMatches(true,0,"Bearer ",0,7))throw new AccessDeniedException("A bearer token is required");EffectiveFeaturePermission p=client.resolve(FEATURE,token);boolean ok=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case ARCHIVE->p.canDelete();case SUBMIT->p.canSubmit();case APPROVE->p.canApprove();default->false;};if(!ok||!p.administrator()&&p.dataScope()!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("RSP recruitment planning action requires agency-wide permission");return p;}}
